package com.myaaptha.domain.health;import jakarta.validation.Valid;import java.security.Principal;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/health") public class HealthController{private final HealthService service;private final HealthReportAnalyzer analyzer;public HealthController(HealthService s,HealthReportAnalyzer a){service=s;analyzer=a;}@GetMapping("/ai-status") public java.util.Map<String,Object> aiStatus(){return java.util.Map.of("configured",analyzer.configured(),"consentRequired",true,"provider","OpenAI");}@GetMapping("/dashboard")public HealthService.Dashboard dashboard(Principal p){return service.dashboard(id(p));}@PostMapping("/reports")public HealthService.Report add(Principal p,@Valid @RequestBody HealthService.ReportInput input){return service.add(id(p),input);}@PostMapping(value="/reports/analyze",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public HealthService.Report analyze(Principal p,@RequestPart("file")MultipartFile file,@RequestParam(defaultValue="false")boolean processingConsent){return service.add(id(p),analyzer.analyze(file,processingConsent));}@DeleteMapping("/reports/{id}")public ResponseEntity<Void>delete(Principal p,@PathVariable Long id){service.delete(id(p),id);return ResponseEntity.noContent().build();}private Long id(Principal p){return Long.valueOf(p.getName());}}
